import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

export default function Dashboard() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAchievement, setShowAchievement] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [filterTutor, setFilterTutor] = useState('all');
  const [filterPeriod, setFilterPeriod] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [studyGoal, setStudyGoal] = useState(localStorage.getItem('studyGoal') || '10');
  const [quickNote, setQuickNote] = useState('');
  const [notesFilter, setNotesFilter] = useState('all');
  const [activityFilter, setActivityFilter] = useState('7d');
  const [heatmapFilter, setHeatmapFilter] = useState('6m');
  const [notesKey, setNotesKey] = useState(0);

  useEffect(() => {
    loadUserData();
    loadSessions();
  }, []);

  useEffect(() => {
    if (sessions.length >= 5 && !localStorage.getItem('achievement_5sessions')) {
      setShowAchievement(true);
      localStorage.setItem('achievement_5sessions', 'true');
      setTimeout(() => setShowAchievement(false), 5000);
    }
  }, [sessions.length]);

  const loadUserData = () => {
    const userData = localStorage.getItem('currentUser');
    if (userData) {
      setUser(JSON.parse(userData));
    }
  };

  const loadSessions = async () => {
    try {
      const token = localStorage.getItem('authToken');
      if (!token) {
        console.log('No token found');
        setLoading(false);
        return;
      }

      const response = await fetch('http://localhost:8000/api/sessions', {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      if (response.ok) {
        const data = await response.json();
        console.log('✅ Sessions loaded:', data);
        setSessions(data);
      } else {
        console.error('❌ Failed to load sessions:', response.status);
      }
    } catch (error) {
      console.error('❌ Error loading sessions:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate('/auth', { replace: true });
  };

  const handleStartSession = (tutorId, subject) => {
    const roomId = `room_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    console.log('🚀 Starting NEW session with tutorId:', tutorId, 'subject:', subject);
    navigate(`/video/${roomId}`, { 
      state: { 
        tutorId: tutorId, 
        subject: subject, 
        resuming: false 
      },
      replace: true
    });
  };

  const handleResumeSession = (session) => {
    navigate(`/video/${session.session_id}`, { 
      state: { 
        tutorId: session.tutor_id,
        subject: session.subject, 
        resuming: true 
      },
      replace: true
    });
  };

  const handleSaveGoal = () => {
    localStorage.setItem('studyGoal', studyGoal);
    alert('Weekly goal updated!');
  };

  const handleSaveNote = () => {
    if (!quickNote.trim()) return;
    const notes = JSON.parse(localStorage.getItem('quickNotes') || '[]');
    notes.unshift({
      id: Date.now(),
      text: quickNote,
      date: new Date().toISOString()
    });
    localStorage.setItem('quickNotes', JSON.stringify(notes));
    setQuickNote('');
    setNotesKey(prev => prev + 1);
    alert('Note saved!');
  };

  const handleDeleteNote = (noteId) => {
    const notes = JSON.parse(localStorage.getItem('quickNotes') || '[]');
    const filtered = notes.filter(n => n.id !== noteId);
    localStorage.setItem('quickNotes', JSON.stringify(filtered));
    setNotesKey(prev => prev + 1);
  };

  const tutors = [
    { 
      id: 'omkar_ai',
      name: 'Omkar', 
      subject: 'AI & Machine Learning', 
      description: 'Expert in Artificial Intelligence and Machine Learning', 
      specialty: 'Neural Networks, Deep Learning, NLP',
      rating: 4.9,
      students: 234
    },
    { 
      id: 'priya_biology',
      name: 'Priya', 
      subject: 'Biology', 
      description: 'Passionate Biology tutor specializing in life sciences', 
      specialty: 'Genetics, Cell Biology, Physiology',
      rating: 4.8,
      students: 189
    }
  ];

  const calculateStudyHours = () => {
    const totalMinutes = sessions.reduce((sum, session) => sum + 30, 0);
    return (totalMinutes / 60).toFixed(1);
  };

  const streak = Math.min(sessions.length, 7);
  const totalHours = calculateStudyHours();

  const getFilteredSessions = () => {
    return sessions.filter(session => {
      const matchesTutor = filterTutor === 'all' || 
        (filterTutor === 'omkar' && session.tutor_id === 'omkar_ai') ||
        (filterTutor === 'priya' && session.tutor_id === 'priya_biology');

      const sessionDate = new Date(session.created_at);
      const now = new Date();
      let matchesPeriod = true;

      if (filterPeriod === '7d') {
        const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        matchesPeriod = sessionDate >= weekAgo;
      } else if (filterPeriod === '1m') {
        const monthAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        matchesPeriod = sessionDate >= monthAgo;
      } else if (filterPeriod === '3m') {
        const threeMonthsAgo = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
        matchesPeriod = sessionDate >= threeMonthsAgo;
      }

      const matchesSearch = searchTerm === '' || 
        session.tutor_id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        session.session_id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (session.tutor_id === 'omkar_ai' && 'ai machine learning neural'.includes(searchTerm.toLowerCase())) ||
        (session.tutor_id === 'priya_biology' && 'biology cell dna genetics'.includes(searchTerm.toLowerCase()));

      return matchesTutor && matchesPeriod && matchesSearch;
    });
  };

  const filteredSessions = getFilteredSessions();

  const getActivityData = () => {
    let days = 7;
    if (activityFilter === '1m') days = 30;
    if (activityFilter === '3m') days = 90;
    if (activityFilter === '6m') days = 180;

    const activityDays = Array.from({ length: days }, (_, i) => {
      const date = new Date();
      date.setDate(date.getDate() - (days - 1 - i));
      return date.toISOString().split('T')[0];
    });

    return activityDays.map(date => {
      const count = sessions.filter(s => 
        new Date(s.created_at).toISOString().split('T')[0] === date
      ).length;
      return { date, count };
    });
  };

  const activityData = getActivityData();

  const getLast7DaysActivity = () => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const date = new Date();
      date.setDate(date.getDate() - (6 - i));
      return date.toISOString().split('T')[0];
    });

    return last7Days.map(date => {
      const count = sessions.filter(s => 
        new Date(s.created_at).toISOString().split('T')[0] === date
      ).length;
      return { date, count };
    });
  };

  const weeklyActivity = activityFilter === '7d' ? getLast7DaysActivity() : activityData;

  const getFilteredNotes = () => {
    const notes = JSON.parse(localStorage.getItem('quickNotes') || '[]');

    if (notesFilter === 'all') return notes;

    const now = new Date();
    return notes.filter(note => {
      const noteDate = new Date(note.date);

      if (notesFilter === 'today') {
        return noteDate.toDateString() === now.toDateString();
      } else if (notesFilter === '7d') {
        const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        return noteDate >= weekAgo;
      } else if (notesFilter === '1m') {
        const monthAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        return noteDate >= monthAgo;
      }
      return true;
    });
  };

  const filteredNotes = getFilteredNotes();

  const getHeatmapData = () => {
    const today = new Date();
    let daysBack = 180;

    if (heatmapFilter === '7d') daysBack = 7;
    if (heatmapFilter === '1m') daysBack = 30;
    if (heatmapFilter === '3m') daysBack = 90;
    if (heatmapFilter === '6m') daysBack = 180;

    const startDate = new Date(today.getTime() - daysBack * 24 * 60 * 60 * 1000);

    const heatmapData = [];
    let currentDate = new Date(startDate);

    while (currentDate <= today) {
      const dateStr = currentDate.toISOString().split('T')[0];
      const count = sessions.filter(s => 
        new Date(s.created_at).toISOString().split('T')[0] === dateStr
      ).length;

      heatmapData.push({
        date: dateStr,
        count: count,
        month: currentDate.toLocaleDateString('en-US', { month: 'short' }),
        day: currentDate.getDay()
      });

      currentDate.setDate(currentDate.getDate() + 1);
    }

    return heatmapData;
  };

  const heatmapData = getHeatmapData();

  const getHeatColor = (count) => {
    if (count === 0) return 'bg-slate-800';
    if (count === 1) return 'bg-indigo-900';
    if (count === 2) return 'bg-indigo-700';
    if (count >= 3) return 'bg-indigo-500';
    return 'bg-slate-800';
  };

  const renderTutorsView = () => (
    <div className="p-8 max-w-7xl mx-auto">
      <div className="mb-12">
        <h2 className="text-3xl font-semibold text-white mb-2">Choose Your AI Tutor</h2>
        <p className="text-slate-400">Start a personalized learning session</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {tutors.map((tutor) => (
          <div 
            key={tutor.id}
            className="bg-slate-800/60 border border-slate-700 hover:border-slate-600 rounded-lg p-6 transition-all duration-200 hover:shadow-lg group"
          >
            <div className="flex items-start justify-between mb-5">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-slate-700 rounded-lg flex items-center justify-center">
                  <span className="text-slate-200 font-semibold text-lg">{tutor.name.charAt(0)}</span>
                </div>
                <div>
                  <h4 className="text-lg font-semibold text-white mb-1">{tutor.name}</h4>
                  <div className="flex items-center gap-2">
                    <svg className="w-4 h-4 text-amber-500" fill="currentColor" viewBox="0 0 20 20">
                      <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
                    </svg>
                    <span className="text-sm text-slate-300 font-medium">{tutor.rating}</span>
                  </div>
                </div>
              </div>
              <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>
            </div>

            <div className="mb-4">
              <span className="inline-block px-3 py-1 bg-slate-700/50 text-slate-200 rounded text-xs font-medium mb-3">
                {tutor.subject}
              </span>
              <p className="text-sm text-slate-300 leading-relaxed">{tutor.description}</p>
            </div>

            <div className="border-t border-slate-700 pt-4 mb-5">
              <div className="text-xs text-slate-500 mb-2">Specialties</div>
              <div className="flex flex-wrap gap-2">
                {tutor.specialty.split(', ').map((spec, idx) => (
                  <span key={idx} className="px-2 py-1 bg-slate-700/30 text-slate-300 rounded text-xs">
                    {spec}
                  </span>
                ))}
              </div>
            </div>

            <button
              onClick={() => handleStartSession(tutor.id, tutor.subject)}
              className="w-full px-4 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg font-medium text-sm transition-colors flex items-center justify-center gap-2"
            >
              Start Session
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
              </svg>
            </button>
          </div>
        ))}
      </div>
    </div>
  );

  const renderNotesView = () => (
    <div className="p-8 max-w-7xl mx-auto">
      <div className="mb-12">
        <h2 className="text-3xl font-semibold text-white mb-2">Notes</h2>
        <p className="text-slate-400">Keep track of important insights</p>
      </div>

      <div className="bg-slate-800/60 border border-slate-700 rounded-lg p-6 mb-6">
        <h3 className="text-base font-semibold text-white mb-4">Create Note</h3>
        <div className="flex gap-3">
          <input
            type="text"
            value={quickNote}
            onChange={(e) => setQuickNote(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSaveNote()}
            placeholder="Write something..."
            className="flex-1 px-4 py-2.5 bg-slate-700/50 border border-slate-600 rounded-lg text-sm text-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
          />
          <button
            onClick={handleSaveNote}
            className="px-5 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg font-medium text-sm transition-colors"
          >
            Add Note
          </button>
        </div>
      </div>

      <div className="flex gap-2 mb-6">
        {[
          { value: 'all', label: 'All' },
          { value: 'today', label: 'Today' },
          { value: '7d', label: '7 Days' },
          { value: '1m', label: '1 Month' }
        ].map(({ value, label }) => (
          <button
            key={value}
            onClick={() => setNotesFilter(value)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              notesFilter === value
                ? 'bg-indigo-600 text-white'
                : 'bg-slate-700/50 text-slate-300 hover:text-white hover:bg-slate-700'
            }`}
          >
            {label}
          </button>
        ))}
      </div>

      <div className="mb-4">
        <p className="text-sm text-slate-400">
          {filteredNotes.length} {filteredNotes.length === 1 ? 'note' : 'notes'}
        </p>
      </div>

      {filteredNotes.length === 0 ? (
        <div className="bg-slate-800/30 border border-slate-700 rounded-lg p-16 text-center">
          <div className="w-16 h-16 bg-slate-700 rounded-lg flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
            </svg>
          </div>
          <h4 className="text-base font-medium text-slate-200 mb-1">No notes yet</h4>
          <p className="text-sm text-slate-400">Start adding notes to keep track of information</p>
        </div>
      ) : (
        <div className="space-y-3">
          {filteredNotes.map((note) => (
            <div 
              key={note.id}
              className="bg-slate-800/60 border border-slate-700 hover:border-slate-600 rounded-lg p-4 transition-colors group"
            >
              <div className="flex items-start justify-between gap-4">
                <div className="flex-1">
                  <p className="text-sm text-slate-100 leading-relaxed mb-2">{note.text}</p>
                  <div className="flex items-center gap-2 text-xs text-slate-400">
                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
