          </div>
        </div>

        <div className="p-4 border-t border-slate-800">
          <div className="flex items-center gap-3 px-3 py-2.5 bg-slate-800/50 rounded-lg mb-3">
            <div className="w-9 h-9 bg-slate-700 rounded-lg flex items-center justify-center text-slate-200 font-medium text-sm">
              {user?.name?.charAt(0)?.toUpperCase() || 'S'}
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-sm font-medium text-white truncate">{user?.name || 'Student'}</div>
              <div className="text-xs text-slate-400 truncate">{user?.email}</div>
            </div>
          </div>
          <button 
            onClick={handleLogout}
            className="w-full px-3 py-2.5 bg-slate-800 hover:bg-slate-700 text-slate-300 hover:text-white rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
            </svg>
            Logout
          </button>
        </div>
      </aside>

      {/* Main Content - Darker background to contrast with sidebar */}
      <main className="flex-1 overflow-y-auto bg-slate-950" key={notesKey}>
        {activeView === 'dashboard' && renderDashboardView()}
        {activeView === 'tutors' && renderTutorsView()}
        {activeView === 'history' && renderHistoryView()}
        {activeView === 'notes' && renderNotesView()}
      </main>
    </div>
  );
}
